const IMG={pastry:"data:image/jpeg;base64,",icons:["data:image/png;base64,","data:image/png;base64,","data:image/png;base64,","data:image/png;base64,","data:image/png;base64,","data:image/png;base64,"]};
const slideHTML=`<div class="slide"><div class="t"><h2>Наш каталог</h2><p>Свіжа випічна<br>щодня</p><a class="btn" href="#catalog">Переглянути більше</a></div><img src="${IMG.pastry}" alt="Круасан, булочка, мафін"></div>`;
const S=document.getElementById('slides');S.innerHTML=slideHTML.repeat(3);
let cur=0;const go=d=>{cur=(cur+d+3)%3;S.style.transform=`translateX(-${cur*100}%)`};
prev.onclick=()=>go(-1);next.onclick=()=>go(1);
let timer=setInterval(()=>go(1),5000);
document.getElementById('catalog').onmouseenter=()=>clearInterval(timer);
const A=[["НАТУРАЛЬНІ ІНГРЕДІЄНТИ","Тільки якісне борошно, свіжа продукція та без шкідливих добавок."],["ТРАДИЦІЙНІ РЕЦЕПТИ","Перевірені часом технології та смакові рецептури."],["СВІЖІСТЬ КОЖНОГО ДНЯ","Випікаємо щодня, щоб ви отримували найсвіжіше."],["ЛЮБОВ ДО СПРАВИ","Ми піклуємося про кожен виріб, бо знаємо, що це — ваша турбота про рідних."],["ЗРУЧНА ДОСТАВКА","Швидко, зручно, у будь-який куточок міста."],["ПІДТРИМКА 24/7","Ми завжди поруч, щоб відповісти на всі ваші питання."]];
cols.innerHTML=A.map((a,i)=>`<div class="col"><img src="${IMG.icons[i]}" alt=""><h3>${a[0]}</h3><p>${a[1]}</p></div>`).join('');
const links=document.querySelectorAll('nav a');
links.forEach(l=>l.onclick=()=>{links.forEach(x=>x.classList.remove('on'));l.classList.add('on')});
form.onsubmit=ev=>{ev.preventDefault();const ok=document.getElementById('ok');
if(!n.value.trim()||!/^\S+@\S+\.\S+$/.test(e.value)){ok.style.display='block';ok.textContent='Будь ласка, заповніть ПІБ та коректний імейл.';return}
ok.style.display='block';ok.textContent='Дякуємо, що ви з нами! Ваш відгук надіслано.';form.reset()};
